class Solution:
    def findValidPair(self, s: str) -> str:
        from collections import Counter

        # Count the frequency of each digit in the string s
        digit_counts = Counter(s)

        # Iterate through the string s to find adjacent pairs
        for i in range(len(s) - 1):
            d1 = int(s[i])
            d2 = int(s[i+1])

            # Check if the first digit is not equal to the second digit
            if d1 == d2:
                continue

            # Check if the counts of each digit in the pair match the numeric value of the digit
            # The condition is: each digit in the pair appears in s exactly as many times as its numeric value.
            # So, if we are looking for pair (d1, d2), we need count(d1) == d1 and count(d2) == d2.

            if d1 in digit_counts and d2 in digit_counts:
                if digit_counts[d1] == d1 and digit_counts[d2] == d2:
                    return str(d1) + str(d2)

        return ""
