class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Handle edge cases
        if not nums:
            return 0

        # Use dynamic programming to find maximum sum of unique subarray
        # dp[i] = maximum sum of a valid subarray ending at index i
        # where all elements in the subarray are unique

        n = len(nums)
        dp = [0] * n
        max_sum = 0

        # For each position, try all possible unique subarrays ending there
        for i in range(n):
            current_sum = 0
            # Try all subarrays ending at i
            for j in range(i, -1, -1):
                # Check if all elements in nums[j:i+1] are unique
                is_unique = True
                for k in range(j, i + 1):
                    if nums[k] in nums[j+1:i+1]:  # Check if element exists in subarray
                        is_unique = False
                        break

                # If unique, update max sum
                if is_unique:
                    current_sum += nums[i]
                    dp[i] = max(dp[i], current_sum)

        return max_sum
