class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        n = len(grid)
        m = len(grid[0])

        # Create a list of (value, row, col) tuples
        elements = []
        for r in range(n):
            for c in range(m):
                elements.append((grid[r][c], r, c))

        # Sort by value descending
        elements.sort(reverse=True, key=lambda x: x[0])

        # Priority queue to store (value, row, col)
        pq = []
        total_elements = 0

        # Select elements greedily
        for value, row, col in elements:
            if total_elements >= k:
                break

            # Check if we can select from this row
            if total_elements >= k:
                break

            # Check if we can select from this row
            if row < n and col < m:
                # Check if we can select from this row
                if row < n:
                    if limits[row] > 0:
                        heapq.heappush(pq, (value, row, col))
                        total_elements += 1
                        if total_elements >= k:
                            break
                    else:
                        # Row is exhausted
                        pass
                else:
                    # Column exhausted
                    pass

        # Return the sum of selected elements
        return sum(grid[r][c] for r, c in elements if total_elements > 0)
